INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$Agencia de marketing digital con sede en Friuli (Italia) y equipo entre Italia y Latinoamérica. Clientes: pymes italianas (restaurantes, hoteles, tiendas, construcción, clínicas, consultoras). Los clientes hablan italiano; el equipo trabaja en español e italiano. Servicios: redes sociales, publicidad (Meta y Google Ads), webs y e-commerce (staging → checklist → entrega), SEO y GEO (Google y buscadores IA), consultoría e IA (estándar Harness), eventos y promociones.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$1) Un solo lugar para cada cosa: tarea → Monday; conversación → canal del cliente; documento → Brain (Drive); decisión → registro de modificaciones. 2) Quien produce no juzga: otra persona y el controlador IA verifican. 3) Fecha cierta o nada: cada promesa tiene fecha y responsable; si no se cumple, se reprograma avisando. 4) El cliente siempre sabe qué pasa: respuesta en 4 horas laborables, recap de cada llamada en 24 horas, informe mensual antes del día 5.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$1. Si no está en Monday, no existe. 2. Nunca se trabaja desde un audio ni desde una conversación suelta. 3. Quien produce no aprueba: otra persona y la IA confirman. 4. Antes de enviar: TESTO — DATA — PREZZO — NOME — CTA — VERSIONE. 5. El cliente siempre sabe qué pasa: 4 horas, fecha cierta. 6. Lo del cliente va al canal del cliente; nada en privado. 7. Contraseñas nunca por chat: solo en el gestor compartido. 8. Los clientes en riesgo van primero. 9. Lo terminado se cierra hoy; lo pendiente se reprograma y se avisa. 10. Preguntar antes de improvisar.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$El cliente escribe libre en su grupo (audios, fotos, mensajes). Nada es operativo hasta que se transforma en el resumen estándar: "MODIFICHE DA APPLICARE – POST 03: testo / data / orario / immagine / CTA". Se produce solo desde el resumen y con tarea en Monday. Después, grupo "QA – Cliente": controlador IA + segunda persona confirman con ✅ TESTO OK, ✅ DATE/PREZZI OK, ✅ GRAFICA OK y ➡️ PUÒ ESSERE INVIATO. Al cliente solo va lo que dice PUÒ ESSERE INVIATO. Webs: captura + URL de staging en el grupo QA antes de publicar. Nunca se envía una gráfica recién exportada. Los audios se transcriben al resumen y se confirman con el cliente.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$1) Si no está en Monday, no existe: cada pedido, promesa o idea es un ítem. 2) Un ítem tiene siempre 5 campos: título en italiano, descripción en español, responsable, fecha, prioridad. 3) Cada cliente tiene su board: workspace Insiderslab Team → "Cliente · Operativo Interno"; propuestas comerciales → Offerte Commerciali. 4) Lo terminado se cierra hoy; lo no hecho se reprograma con fecha real y se avisa. Cero vencidos en clientes en riesgo. 5) Cada llamada (Fireflies) tiene recap en 24 h y sus acciones en Monday.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$TESTO: ¿texto final aprobado, en italiano, sin errores? DATA: ¿fecha y hora correctas y coherentes con el calendario del cliente? PREZZO: ¿precios, ofertas y condiciones iguales a lo que dijo el cliente? NOME: ¿nombre del local, producto o referente bien escrito? CTA: ¿lleva al link, teléfono o perfil correctos? VERSIONE: ¿es la versión que aprobó el grupo QA y no una anterior?$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$8:00 IT (2:00 VE): ronda automática de Vice-Ste con 3 prioridades; Dirección aprueba. 7:00 VE (13:00 IT): inicio, 30' fijos: asignaciones → WhatsApp/Slack de clientes en riesgo → responder a quien espera (SLA 4 h). 7:30–10:00 VE: ejecutar asignaciones (resumen → Monday → registro de modificaciones). 10:00–13:00 VE: producción y QA; envíos al cliente antes de las 13:00 VE (19:00 IT). 13:00–15:00 VE: trabajo de fondo (grillas, recontactos comerciales, preparar el día siguiente). Cierre: Monday al día y una línea a Dirección con cerrado y bloqueado. Reuniones fijas: lunes 14:00 IT planning (30'), miércoles bloqueos (15'), viernes 16:00 IT cierre (30').$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$Monday: todas las tareas, un board por cliente (si no está, no existe). Slack: comunicación interna, #cliente-*, #fireflies-task. WhatsApp Web: canal de la mayoría de los clientes y grupos QA; nunca se trabaja desde un audio. Fireflies: graba y transcribe; recap en 24 h y tareas en Monday. Brain (Drive): documentos, contratos, gráficas, wiki; nada se queda en el WhatsApp. Gmail y Calendar: toda llamada tiene evento con Fireflies. Metricool y Canva: solo se programa lo aprobado. n8n y Claude: la IA propone, una persona verifica.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$En Clientes/Clients cada cliente tiene su carpeta numerada con el mismo esqueleto: 01 MATERIALES (lo que manda el cliente), 02 Diseño Gráfico (gráficas aprobadas por mes o campaña, con versión), 03 Social Media (grilla "Contenuti - Cliente 2026"), 04 Performance (campañas, informes, referencias de accesos), 05 Web (checklists, capturas de staging, contenidos, auditorías SEO), y en la raíz briefing, tono de voz, documento de solicitudes y recaps. Si no encuentras algo, está mal guardado: se mueve a su sitio y se avisa.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$Hoja "Contenuti - Cliente 2026" en la carpeta del cliente: una fila por pieza y perfil, con fecha, formato, texto, gráfica, versión, revisor QA, aprobación del cliente y URL publicada. La grilla es la verdad: sin estado "aprobado" no se programa en Metricool. Si el cliente cambia algo por WhatsApp, primero la grilla y después la gráfica. Si v1 pasa a v2, se vuelven a comprobar las aprobaciones. Programado no significa publicado. Se revisa cada viernes (P6).$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$Dirección (Ste): prioridades, llamadas importantes, presupuestos y renegociaciones. Vice-Ste (IA): lee Fireflies, Slack, WhatsApp, Monday, Gmail y Calendar, prepara ronda, recaps y borradores; no envía nada solo. Performance, SEO y Ads (Mihir): Meta y Google Ads, SEO, informes; trabaja en inglés; se le pide por Slack con la tarea en Monday. Diseño gráfico (Arianna): gráficas y creatividades; nada sale sin QA. Asistente operativa: solicitudes, resumen estándar, ítems de Monday, registro de modificaciones, accesos. Coordinación de contenidos: grillas, QC único de textos, aprobación del envío, control del viernes, informe mensual.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, content) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'block', $kb$Servicio: solicitudes respondidas dentro del SLA y recaps en 24 h. Entrega: puntualidad respecto a la fecha original y publicaciones verificadas. Calidad: QA al primer intento y errores que vuelven al cliente. Capacidad: tiempo total, incluida revisión y retrabajo. Un dato ausente es N/D, nunca cero.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Cuánto tiempo tengo para responder a un cliente?$kb$, $kb$4 horas laborables, con un próximo paso y una fecha de actualización. Recap de cada llamada en 24 h.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Puedo trabajar desde un audio del cliente?$kb$, $kb$No. Se transcribe al resumen "MODIFICHE DA APPLICARE", se confirma con el cliente y se carga en Monday (P13).$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Cómo creo bien un ítem en Monday?$kb$, $kb$5 campos: título en italiano, descripción en español, responsable, fecha, prioridad. En el board "Cliente · Operativo Interno" del cliente (P14).$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Puedo mandar la gráfica al cliente?$kb$, $kb$Solo si en el grupo "QA – Cliente" tiene ✅ TESTO, ✅ DATE/PREZZI, ✅ GRAFICA y ➡️ PUÒ ESSERE INVIATO, y pasaste el mini-check.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Dónde guardo lo que manda el cliente?$kb$, $kb$En su carpeta del Brain, en 01 MATERIALES. Nada se queda en WhatsApp.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$Me pidieron una contraseña por chat$kb$, $kb$No se comparten por chat: solo en el gestor compartido. Avisa a Dirección si alguien la pide por chat.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿A qué hora son las reuniones fijas?$kb$, $kb$Lunes 14:00 IT planning (30'), miércoles bloqueos (15'), viernes 16:00 IT cierre (30').$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$No sé cómo seguir con una tarea$kb$, $kb$Pregunta antes de improvisar: escribe a Dirección con lo que tienes, lo que falta y la fecha.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$El cliente cambió algo por WhatsApp$kb$, $kb$Primero se actualiza la grilla, después la gráfica, y se vuelve a pasar por QA si cambió la versión.$kb$);
INSERT INTO kb_entry (id, organization_id, kind, question, answer) VALUES ('kb_' || substr(md5(random()::text || clock_timestamp()::text), 1, 20), :'org', 'qa', $kb$¿Puedo programar un post en Metricool?$kb$, $kb$Solo si en la grilla está en estado "aprobado". Programado no es publicado: verifica la URL final.$kb$);
